/**
 * @name Command injection
 * @description Using os.system, subprocess, or similar with untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // SystemCommandExecution is a concept, not a class with getACommandArgument()
    // Use API graphs to find command execution calls
    exists(DataFlow::CallCfgNode call |
      // os.system calls
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // subprocess.call, subprocess.run, subprocess.Popen, etc.
      call = API::moduleImport("subprocess").getMember(["call", "run", "Popen", "check_call", "check_output"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // os.popen calls
      call = API::moduleImport("os").getMember("popen").getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal
 * @description Using user input in file paths without proper sanitization can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    )
    or
    // os.path.join with user input
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("path").getMember("join").getACall() and
      // Check any argument could be tainted
      exists(int i | sink = call.getArg(i))
    )
    or
    // os.open, os.makedirs, etc.
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember(["open", "makedirs", "mkdir", "remove", "unlink", "rename"]).getACall() and
      sink = call.getArg(0)
    )
    or
    // pathlib operations
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pathlib").getMember("Path").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

/**
 * @name HTTP header injection
 * @description User-controlled input in HTTP headers can lead to HTTP response splitting or header injection
 * @kind path-problem
 * @problem.severity error
 * @id py/http-header-injection
 * @tags security
 *        external/cwe/cwe-113
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module HeaderInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for header setting in HTTP requests
    // Look for calls that set headers in urllib3 or HTTP requests
    exists(DataFlow::CallCfgNode call |
      // urllib3 request methods that accept headers
      call = API::moduleImport("urllib3").getMember(["request", "urlopen", "PoolManager", "HTTPConnectionPool"]).getACall() and
      // Headers are typically passed as a dictionary argument
      exists(int i | sink = call.getArg(i))
    )
    or
    // Direct header manipulation
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("urllib3").getMember("_collections").getMember("HTTPHeaderDict").getMember(["add", "__setitem__", "update"]).getACall() and
      sink = call.getArg(1)  // Value argument for header
    )
  }
}

module HeaderInjectionFlow = TaintTracking::Global<HeaderInjectionConfig>;
import HeaderInjectionFlow::PathGraph

from HeaderInjectionFlow::PathNode source, HeaderInjectionFlow::PathNode sink
where HeaderInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "HTTP header injection from $@.", source.getNode(), "user input"

/**
 * @name Server-Side Request Forgery (SSRF)
 * @description User-controlled URLs can be used to make requests to internal resources
 * @kind path-problem
 * @problem.severity error
 * @id py/ssrf
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // urllib3 request methods that accept URLs
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("urllib3").getMember(["request", "urlopen", "HTTPConnectionPool"]).getACall() and
      sink = call.getArg(0)  // URL argument
    )
    or
    // PoolManager.request
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("urllib3").getMember("PoolManager").getMember("request").getACall() and
      sink = call.getArg(1)  // URL argument (after method)
    )
  }
}

module SSRFflow = TaintTracking::Global<SSRFConfig>;
import SSRFflow::PathGraph

from SSRFflow::PathNode source, SSRFflow::PathNode sink
where SSRFflow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF vulnerability from $@.", source.getNode(), "user input"

/**
 * @name XML External Entity (XXE) vulnerability
 * @description Parsing XML with external entity expansion enabled can lead to file disclosure or SSRF
 * @kind path-problem
 * @problem.severity error
 * @id py/xxe
 * @tags security
 *        external/cwe/cwe-611
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XXEConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // XML parsing with potentially dangerous settings
    exists(DataFlow::CallCfgNode call |
      // xml.etree.ElementTree
      call = API::moduleImport("xml.etree.ElementTree").getMember(["parse", "fromstring"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // lxml
      call = API::moduleImport("lxml").getMember(["etree", "objectify"]).getMember(["parse", "fromstring"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // xml.dom.minidom
      call = API::moduleImport("xml.dom.minidom").getMember(["parse", "parseString"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module XXEFlow = TaintTracking::Global<XXEConfig>;
import XXEFlow::PathGraph

from XXEFlow::PathNode source, XXEFlow::PathNode sink
where XXEFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XXE vulnerability from $@.", source.getNode(), "user input"
